#include <bits/stdc++.h>
using namespace std;


#define ll long long

int main() {
	// your code goes here
	int t;
	cin >> t;
	while(t--){
	    ll n;
	    cin >> n;
	    vector<ll> arr(3*n), p(3*n+1);
	    for(int i = 0; i < 3*n; i++){
	        cin >> arr[i];
	    }
	    
	    sort(arr.begin(), arr.end());
	    arr.push_back(0);
	    reverse(arr.begin(), arr.end());
	    
	    for(int i = 1; i <= 3*n; i++){
	        p[i] = p[i-1] + arr[i];
	    }
	    
	    function <ll(ll)> bs =[&](ll a) -> ll{
	        ll l = 1, r = n - a;
	        ll ans = 0;
	        
	        while(l <= r){
	            ll b = (l+r)/2;
	            ll m = b;
	            ll c = n - a - b;
	            ll ans1 = 4*p[a + 2*b] - 4*p[a] + 3*p[a + 2*b + 3*c] - 3*p[a + 2*b];
	            b--;
	            c++;
	            ll ans2 = 4*p[a + 2*b] - 4*p[a] + 3*p[a + 2*b + 3*c] - 3*p[a + 2*b];
	            
	            ans = max(ans, max(ans1, ans2));
	            if(ans1 >= ans2){
	                l = m + 1;
	            }
	            else{
	                r = m - 1;
	            }
	            
	        }
	        
	        return ans;
	    };
	    
	    ll s = 0;
	    for(int i = 0; i <= n; i++){
	        if(i == 0){
	            s = bs(0);
	        }
	        else{
	            s = max(s, 6*p[i] + bs(i));
	        }
	    }
	    cout << s << endl;
	}

}
